  --amber: #f5b83d;
  --green: #3fce7d;
  --cyan: #46c2d8;
  --coral: #f27d6d;
  --violet: #a78bfa;
  --radius: 10px;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
  padding: 20px 22px 40px;
}
