.detail {
  border: 1px solid var(--amber); background: var(--panel); border-radius: var(--radius);
  padding: 16px 18px; margin-bottom: 14px;
}
.detail h2 { margin: 0 0 2px; font-size: 22px; }
.detail .tag { color: var(--muted); font-size: 13px; margin: 0 0 12px; }
