.panels { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-top: 22px; }
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px 18px; }
.panel h2 { margin: 0 0 8px; font-size: 17px; }
.panel p { color: var(--muted); margin: 0 0 10px; }
.formula { margin: 0 0 10px; padding-left: 20px; color: var(--text); }
