.note { font-size: 13px; }
.live th, .live td { padding: 6px 8px; border-bottom: 1px solid var(--line); text-align: left; font-size: 13px; }
.live thead th { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.4px; }
.foot { color: var(--faint); font-size: 12px; margin-top: 22px; }
@media (max-width: 900px) {
  .panels { grid-template-columns: 1fr; }
  .meta { text-align: left; }
  body { padding: 14px 12px 32px; }
}
